#include <iostream>
#include <memory>
struct A; struct B;
struct A { std::shared_ptr<B> b; ~A(){ std::cout << "~A\n"; } };
struct B { std::shared_ptr<A> a; ~B(){ std::cout << "~B\n"; } };
int main() {
    auto a = std::make_shared<A>();
    auto b = std::make_shared<B>();
    a->b = b; b->a = a;                  // 互相强引用：强计数互相钉死
    std::cout << "count a=" << a.use_count() << " b=" << b.use_count() << '\n';
}                                        // 离开作用域析构不触发（无 ~A ~B 输出 = 泄漏）
